sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {


    // MSSOTIQUBE-532
    var ctacCode = current.status.ctac_code;
    var tradeMismatches = current.trade_mismatches_be_managed_outside_iqube_instance;

	//MSSOTIQUBE-1331, setting this flag as true because if counterpartycode is not provided, case should be created.
    var isClientandProcessLive = true;

    if ((ctacCode == 'AMSM' || ctacCode == 'TMSM') && tradeMismatches == true) {
        //DO NOT CANCEL THE EXISITNG OPEN CASE FOR TMSM OR AMSM, DEFECT MSSRBX-1183
    } else {
        if (!current.isNewRecord()) {

            //MSSOTIQUBE-1094 --> To handle errors for case updation
            // new inbound event received for the trade, to Cancel all active case under this trade and update the BPI case_created flag to false.
            try {
                var tradecase = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');
                tradecase.addQuery('financial_object', current.financial_object_record);
                tradecase.addActiveQuery();
                tradecase.query();
                while (tradecase.next()) {
                    tradecase.auto_close = true;
                    tradecase.state = 7;
                    tradecase.update();

                }
                current.is_case_created = false;
                current.update();
            } catch (error) {
                gs.error("Tradecase Closure and Exep case- Trade case updation failed: Trade ID:" + current.financial_object_record + "Error: " + error.message);
            }

        }
    }

	//MSSOTIQUBE-1331, Stop Case Creation for Not Live Client and Market_Dev
    var additionalAttributeJson = JSON.parse(current.additional_attributes);
    // Checks the current client and process if they are active
    if (additionalAttributeJson.COUNTERPARTY_CODE != null) {
        isClientandProcessLive = checkClientandProcessLive(current);
    }else{
		gs.error("Counterparty code not provided for : "+current.messageid);
	}

    function checkClientandProcessLive(current) {
        var checkClientLive = new GlideRecord('x_hsb11_hsbc_mss_o_client_and_processes_checklist');
        checkClientLive.addEncodedQuery('client.u_counterparty_code=' + additionalAttributeJson.COUNTERPARTY_CODE + '^business_process_definition=' + current.business_process_definition);
        checkClientLive.query();
        if (checkClientLive.next()) {
            return checkClientLive.active;
        } else {
            return false;
        }
    }


    //Create Trade Case if the trade is in Exception status
    if (current.is_exception == true && isClientandProcessLive == true) {
        var getCaseSuppressionLogicLiveCheck = gs.getProperty('x_hsb11_hsbc_mss_t.case_suppressionlogic_isactive');

        if (getCaseSuppressionLogicLiveCheck == 'true') { //If case suppression logic is true, check the 'is live' flag of the status

            //MSSOTIQUBE-1094 --> To handle errors for case creation
            try {
                var getStatusLiveCheck = new x_hsb11_hsbc_mss_o.caseSuppressionChecks().isStatusLive(current.status);
                if (getStatusLiveCheck) {


                    //Validate if the trade managed outside IQube is true then do not process any mismatch status to create a case
                    // MSSOTIQUBE-532
                    if ((ctacCode == 'AMSM' || ctacCode == 'TMSM') && tradeMismatches == true) {
                        //DO NOT PROCESS AMSM OR TMSM EVENTS
                    } else {
                        var createTradeCaseSuppressionON = new x_hsb11_hsbc_mss_t.HSBCTradeCaseException();
                        createTradeCaseSuppressionON.createHsbcTradeCase(current.financial_object_record, current.status, current.additional_attributes, current.payload, current.object_version, current.event_type, current.objectid_type, current.object_type, current.number, current.messageid, current.source);

                        current.is_case_created = true;
                        current.update();

                    }
                }
            } catch (error) {
                gs.error("Tradecase Closure and Exep case- Trade case creation failed: Trade ID:" + current.financial_object_record + "Error: " + error.message);
            }

        } else { //If case suppression logic is false, ignore suppression logic

            //Validate if the trade managed outside IQube is true then do not process any mismatch status to create a case
            // MSSOTIQUBE-532
            if ((ctacCode == 'AMSM' || ctacCode == 'TMSM') && tradeMismatches == true) {
                //DO NOT PROCESS AMSM OR TMSM EVENTS
            } else {

                //MSSOTIQUBE-1094 --> To handle errors for case creation 
                try {
                    var createTradeCase = new x_hsb11_hsbc_mss_t.HSBCTradeCaseException();
                    createTradeCase.createHsbcTradeCase(current.financial_object_record, current.status, current.additional_attributes, current.payload, current.object_version, current.event_type, current.objectid_type, current.object_type, current.number, current.messageid, current.source);

                    current.is_case_created = true;
                    current.update();

                } catch (error) {
                    gs.error("Tradecase Closure and Exep case- Trade case creation failed: Trade ID:" + current.financial_object_record + "Error: " + error.message);
                }
            }
        }
    }
})(current, previous);
